package com.example.sweetbites.data

import kotlinx.coroutines.flow.Flow

class RecipeRepository(private val dao: RecipeDao) {
    val recipes: Flow<List<Recipe>> = dao.observeAll()
    val favorites: Flow<List<Recipe>> = dao.observeFavorites()
    val recent: Flow<List<Recipe>> = dao.observeRecent()

    suspend fun recipe(id: Int) = dao.getById(id)
    suspend fun toggleFavorite(recipe: Recipe) = dao.setFavorite(recipe.id, !recipe.isFavorite)
    suspend fun markViewed(id: Int) = dao.markViewed(id, System.currentTimeMillis())
    suspend fun seedIfEmpty() = dao.insertAll(seedRecipes)

    companion object {
        val seedRecipes = listOf(
            Recipe(1,"Chocolate Fudge Cake","Cakes","A rich, soft chocolate cake finished with glossy ganache.",25,35,"Medium",8,"🍫","#F2D7D2","1½ cups all-purpose flour|¾ cup cocoa powder|1 cup sugar|2 eggs|½ cup milk|½ cup melted butter|1 tsp baking powder|1 tsp vanilla extract","Preheat oven to 180°C and grease an 8-inch tin.|Whisk flour, cocoa, sugar and baking powder.|Add eggs, milk, butter and vanilla; mix until smooth.|Pour into the tin and bake for 30–35 minutes.|Cool completely, then cover with chocolate ganache.","Do not overmix the batter; it keeps the cake tender."),
            Recipe(2,"Strawberry Cheesecake","Cheesecakes","Creamy cheesecake with a buttery crumb base and berries.",30,45,"Medium",10,"🍓","#F8DCE5","200 g digestive biscuits|80 g melted butter|400 g cream cheese|½ cup sugar|2 eggs|1 tsp vanilla|1 cup strawberries","Crush biscuits and combine with melted butter.|Press into a lined springform tin and chill.|Beat cream cheese, sugar, eggs and vanilla until smooth.|Pour over the base and bake in a water bath at 160°C.|Cool slowly, chill for 4 hours and top with strawberries.","Bring cream cheese to room temperature for a lump-free filling."),
            Recipe(3,"Vanilla Cupcakes","Cupcakes","Fluffy vanilla cupcakes topped with pink buttercream.",15,20,"Easy",12,"🧁","#F8E1E8","1½ cups flour|¾ cup sugar|½ cup softened butter|2 eggs|½ cup milk|1 tsp vanilla|1½ tsp baking powder","Preheat oven to 180°C and line a muffin tray.|Cream butter and sugar until pale and fluffy.|Beat in eggs and vanilla.|Fold in flour and baking powder, alternating with milk.|Divide into cases and bake for 18–20 minutes.|Cool before piping buttercream.","Fill cupcake liners only two-thirds full."),
            Recipe(4,"Fudgy Brownies","Brownies","Dense chocolate brownies with a shiny crackly top.",15,25,"Easy",9,"🍫","#EAD7D0","150 g dark chocolate|100 g butter|¾ cup sugar|2 eggs|½ cup flour|2 tbsp cocoa powder|Pinch of salt","Melt chocolate and butter together, then cool slightly.|Whisk sugar and eggs until glossy.|Stir in chocolate, flour, cocoa and salt.|Spread into a lined square tin.|Bake at 175°C for 22–25 minutes and cool before slicing.","Take them out when the centre still has a few moist crumbs."),
            Recipe(5,"Classic Tiramisu","No Bake","Coffee-soaked layers with a light mascarpone cream.",30,0,"Medium",6,"☕","#E9D9C7","250 g mascarpone|1 cup whipping cream|⅓ cup sugar|1 cup cooled strong coffee|200 g ladyfinger biscuits|Cocoa powder","Whip cream and sugar to soft peaks.|Fold in mascarpone until smooth.|Dip ladyfingers quickly in cooled coffee.|Layer biscuits and cream in a dish.|Repeat layers and dust with cocoa.|Chill for at least 6 hours before serving.","A quick dip keeps the biscuits soft without turning soggy."),
            Recipe(6,"Mango Mousse Cups","Puddings","Airy mango mousse served in individual dessert cups.",20,0,"Easy",4,"🥭","#F8E5B8","1 cup mango puree|1 cup chilled whipping cream|3 tbsp powdered sugar|1 tsp lemon juice|½ tsp gelatin (optional)","Chill a mixing bowl and beaters.|Whip cream with sugar to soft peaks.|Fold mango puree and lemon juice into the cream.|For a firmer set, bloom and dissolve gelatin, then fold in.|Spoon into cups and chill for 3 hours.","Use ripe, sweet mangoes for the brightest flavour."),
            Recipe(7,"Chocolate Chip Cookies","Cookies","Golden cookies with crisp edges and gooey chocolate centres.",15,12,"Easy",16,"🍪","#EBD7C2","1¼ cups flour|½ cup softened butter|½ cup brown sugar|¼ cup white sugar|1 egg|1 tsp vanilla|½ tsp baking soda|¾ cup chocolate chips","Heat oven to 180°C and line a baking tray.|Cream butter and both sugars.|Mix in egg and vanilla.|Fold in flour and baking soda, then chocolate chips.|Scoop onto tray with space between each cookie.|Bake 10–12 minutes; cool on the tray.","Chill the dough for 20 minutes for thicker cookies."),
            Recipe(8,"Lemon Drizzle Loaf","Cakes","A bright lemon loaf with a tangy citrus glaze.",20,40,"Easy",8,"🍋","#F5E8B7","1½ cups flour|¾ cup sugar|½ cup butter|2 eggs|¼ cup milk|Zest of 2 lemons|1 tsp baking powder|3 tbsp lemon juice|½ cup icing sugar","Preheat oven to 175°C and line a loaf tin.|Cream butter and sugar, then beat in eggs.|Fold in flour, baking powder, lemon zest and milk.|Bake for 35–40 minutes until a skewer comes out clean.|Mix lemon juice with icing sugar and drizzle over the warm loaf.","Pour the glaze on while the loaf is still a little warm."),
            Recipe(9,"Red Velvet Cake","Cakes","Tender cocoa cake with a silky cream-cheese frosting.",30,30,"Medium",10,"❤️","#F5D7DD","2 cups flour|1 cup sugar|2 tbsp cocoa|2 eggs|½ cup oil|1 cup buttermilk|1 tsp baking soda|1 tsp vinegar|Red food colouring","Preheat oven to 175°C and prepare two cake tins.|Whisk flour, sugar and cocoa in a bowl.|Mix eggs, oil, buttermilk, vinegar and colouring separately.|Combine wet and dry ingredients just until mixed.|Divide into tins and bake for 25–30 minutes.|Cool and layer with cream-cheese frosting.","Use gel colouring for a deep colour without adding extra liquid."),
            Recipe(10,"No-Bake Oreo Tart","No Bake","A crunchy cookie crust with a silky chocolate filling.",25,0,"Easy",8,"🍪","#E4D8D8","24 chocolate sandwich cookies|70 g melted butter|200 g dark chocolate|200 ml warm cream|1 tbsp butter|Crushed cookies for topping","Crush cookies finely and mix with melted butter.|Press firmly into a tart tin and chill for 20 minutes.|Pour warm cream over chopped chocolate and wait 2 minutes.|Stir until smooth, then mix in butter.|Pour filling into crust and chill for 4 hours.|Top with cookie crumbs before serving.","Press the crust with the base of a glass for an even layer."),
            Recipe(11,"Caramel Pudding","Puddings","Silky baked custard with a golden caramel sauce.",20,40,"Medium",6,"🍮","#F2DFC5","½ cup sugar for caramel|2 cups milk|3 eggs|¼ cup sugar|1 tsp vanilla","Melt caramel sugar in a saucepan until amber and pour into ramekins.|Warm milk gently; do not boil.|Whisk eggs, sugar and vanilla, then slowly add warm milk.|Strain into ramekins over the caramel.|Bake in a water bath at 160°C for 35–40 minutes.|Cool and refrigerate, then invert to serve.","Keep the caramel amber, not dark brown, to avoid bitterness."),
            Recipe(12,"Berry Yogurt Parfait","Healthy","Layers of creamy yogurt, berries and crunchy granola.",10,0,"Easy",2,"🫐","#E2E4F6","1 cup thick Greek yogurt|1 tbsp honey|½ cup mixed berries|½ cup granola|1 tsp chia seeds","Stir honey into the yogurt.|Add a layer of yogurt to each glass.|Top with berries and granola.|Repeat layers and sprinkle with chia seeds.|Serve straight away for a crunchy topping.","Keep granola separate until serving if preparing ahead.")
        )
    }
}
